"""Independent SOW checker: python check.py <week> [schedule.csv]"""
import sys, math, csv
from datetime import datetime, timedelta, timezone
from zoneinfo import ZoneInfo
from collections import defaultdict
week=sys.argv[1]; path=sys.argv[2] if len(sys.argv)>2 else '/app/out/northwind/schedule.csv'
Z=ZoneInfo('America/Chicago'); U=timezone.utc
SLA={'priority':(.9,30),'standard':(.8,20),'vip':(.9,20)}
def pt(s): return datetime.strptime(s,'%Y-%m-%dT%H:%M:%SZ').replace(tzinfo=U)
def erl_sl(a,n,aht,t):
    if a<=0: return 1.0
    if n<=a: return 0.0
    term=1.0; s=1.0
    for k in range(1,n): term*=a/k; s+=term
    term*=a/n; top=term*n/(n-a); pw=top/(s+top)
    return 1-pw*math.exp(-(n-a)*t/aht)
def req(v,aht,q):
    a=v/1800*aht
    if a<=0: return 0
    n=max(1,math.ceil(a))
    while not (erl_sl(a,n,aht,SLA[q][1])>=SLA[q][0]-1e-12 and a/n<=0.85+1e-12): n+=1
    return n
# demand
rows=list(csv.DictReader(open(f'/app/data/northwind/export_{week}.csv')))
dem={}
for r in rows:
    loc=datetime.strptime(r['interval_start_local'],'%Y-%m-%d %H:%M')
    sign=1 if r['utc_offset'][0]=='+' else -1
    off=timedelta(hours=int(r['utc_offset'][1:3]),minutes=int(r['utc_offset'][4:6]))*sign
    t=(loc-off).replace(tzinfo=U)
    dem[(r['queue'],t)]=(float(r['volume']),float(r['aht_sec']))
grid=sorted({t for _,t in dem})
R={}; opn={}
for (q,t),(v,aht) in dem.items():
    l=t.astimezone(Z); h=l.hour+l.minute/60
    lo,hi=(8,20) if q=='vip' else (6,24)
    opn[(q,t)]= lo<=h<hi
    R[(q,t)]=req(v,aht,q) if opn[(q,t)] else 0
    if not opn[(q,t)] and v>0: print('volume outside op hours',q,t)
reqh=sum(R.values())*.5
agents={r['agent_id']:(r['contract'],set(r['skills'].split(';'))) for r in csv.DictReader(open('/app/data/agents/northwind.csv'))}
S=list(csv.DictReader(open(path)))
for r in S: r['s']=pt(r['segment_start_utc']); r['e']=pt(r['segment_end_utc'])
viol=defaultdict(list)
gross=defaultdict(int); brk=defaultdict(int)
byagent=defaultdict(list)
for r in S:
    t=r['s']
    while t<r['e']: gross[(r['queue'],t)]+=1; t+=timedelta(minutes=30)
    byagent[r['agent_id']].append(r)
    if r['queue'] not in agents[r['agent_id']][1]: viol['skill'].append(r['agent_id'])
    if r['break_minutes'] not in ('','0'):
        b=pt(r['break_start_utc']); brk[(r['queue'],b)]+=1
        if b.minute%30: viol['break_align'].append(b)
tpl={'E8':[(6,14)],'D8':[(9,17)],'L8':[(13,21)],'N8':[(16,24)],'P6a':[(7,13)],'P6b':[(15,21)],'P4':[(10,14)],'S44':[(8,12),(16,20)]}
tot_hours=0
for a,rs in byagent.items():
    rs.sort(key=lambda r:r['s'])
    c,sk=agents[a]
    hrs=sum((r['e']-r['s']).total_seconds() for r in rs)/3600; tot_hours+=hrs
    if hrs>(40 if c=='FT' else 24)+1e-9: viol['weekly'].append(a)
    for x,y in zip(rs,rs[1:]):
        if y['s']<x['e']: viol['overlap'].append(a)
    # shifts by local day
    days=defaultdict(list)
    for r in rs: days[r['s'].astimezone(Z).date()].append(r)
    shifts=[]
    for d,l in sorted(days.items()):
        l.sort(key=lambda r:r['s'])
        ids={r['template_id'] for r in l}
        if len(ids)!=1: viol['template_mix'].append((a,d))
        tid=l[0]['template_id']
        exp=[( datetime(d.year,d.month,d.day,tzinfo=Z)+timedelta(hours=h1), datetime(d.year,d.month,d.day,tzinfo=Z)+timedelta(hours=h2)) for h1,h2 in tpl[tid]]
        got=[(r['s'],r['e']) for r in l]
        if [(x.astimezone(U),y.astimezone(U)) for x,y in exp]!=got: viol['template_shape'].append((a,d))
        if len(l)>1 and c!='PT': viol['split_ft'].append(a)
        sh_hours=sum((r['e']-r['s']).total_seconds() for r in l)/3600
        nb=[r for r in l if r['break_minutes'] not in('','0')]
        if sh_hours>=6:
            if len(nb)!=1 or nb[0]['break_minutes']!='20': viol['break_count'].append((a,d))
            else:
                b=pt(nb[0]['break_start_utc']); off=(b-l[0]['s']).total_seconds()/3600
                if not(2<=off<=5): viol['break_window'].append((a,d,off))
                if not(nb[0]['s']<=b and b+timedelta(minutes=20)<=nb[0]['e']): viol['break_inside'].append((a,d))
        elif nb: viol['break_short'].append((a,d))
        shifts.append((l[0]['s'],l[-1]['e'],d,l[0]['queue']))
        if len({r['queue'] for r in l})>1: viol['queue_mix'].append((a,d))
    for x,y in zip(shifts,shifts[1:]):
        if (y[0]-x[1])<timedelta(hours=11): viol['rest'].append((a,x[2],round((y[0]-x[1]).total_seconds()/3600,2)))
    ds=sorted(days)
    run=1
    for d1,d2 in zip(ds,ds[1:]):
        run=run+1 if (d2-d1).days==1 else 1
        if run>5: viol['consec'].append(a); break
# break rule: gross surplus max in window
for a,rs in byagent.items():
    days=defaultdict(list)
    for r in rs: days[r['s'].astimezone(Z).date()].append(r)
    for d,l in days.items():
        l.sort(key=lambda r:r['s'])
        nb=[r for r in l if r['break_minutes'] not in('','0')]
        if not nb: continue
        q=l[0]['queue']; b=pt(nb[0]['break_start_utc']); st=l[0]['s']
        cands=[]
        for r in l:
            t=r['s']
            while t+timedelta(minutes=20)<=r['e']:
                if st+timedelta(hours=2)<=t<=st+timedelta(hours=5): cands.append(t)
                t+=timedelta(minutes=30)
        sur=lambda t: gross[(q,t)]-R[(q,t)]
        if sur(b)<max(sur(t) for t in cands): viol['break_not_max_surplus'].append((a,d))
# vip floor
for t in grid:
    l=t.astimezone(Z); h=l.hour+l.minute/60
    if 6<=h<24 and gross[('vip',t)]<1: viol['vip_floor'].append(t)
att={}; under=0
for q in SLA:
    ops=[t for t in grid if opn[(q,t)]]
    met=sum(1 for t in ops if gross[(q,t)]-brk[(q,t)]>=R[(q,t)])
    att[q]=met/len(ops)
    under+=sum(max(0,R[(q,t)]-(gross[(q,t)]-brk[(q,t)])) for t in grid)*.5
print('intervals',len(grid),'att',{k:round(v,3) for k,v in att.items()},'sched_h',round(tot_hours,1),'req_h',reqh,'ratio',round(tot_hours/reqh,3),'bound',round(1.57*reqh,1),'under',under,'agents',len(byagent))
print('violations',{k:len(v) for k,v in viol.items()} or 'none')
for k,v in viol.items(): print(k,v[:4])
