cd /app; sed -i "s/^search_iterations.*/search_iterations: 300000/" configs/northwind.yaml; for w in 2026-W42 2026-W43 2026-W44; do /usr/bin/env time -f "%es" python -c "
import sys; sys.path.insert(0,'/app')
from wfm.cli import run; run('northwind','$w')" 2>&1 | tail -1; python /tmp/tools/check.py $w; done

